old_string:
  form_intro: 'Please fill out your insurance details using the secure form below.',
  confirmation_template:
    'Hi {{name}}, please confirm your details:\n\n• Name: {{name}}\n• Insurance Type: {{insurance_type}}\n• Company: {{company}}\n\nReply *Yes* to confirm or *No* to cancel.',
  forward_template:
    '📋 *New Insurance Lead*\n\n• Name: {{name}}\n• Phone: {{phone}}\n• Insurance Type: {{insurance_type}}\n• Company: {{company}}\n• Submitted: {{submitted_at}}',
  success_message: 'Thank you! Your details have been confirmed and forwarded to our team. We will contact you shortly.',
  cancel_message: 'Your request has been cancelled. Send *Hi* anytime to start again.',
  already_pending_message: 'You already have a pending request. Please complete the form or reply *Yes* / *No* to your confirmation message.',
};

for (const [key, value] of Object.entries(defaults)) {
  if (Settings.get(key) === null) {
    Settings.set(key, value);
  }
}

new_string:
  form_intro: 'Select Health or Vehicle insurance. Extra fields appear based on your choice.',
  confirmation_template:
    'Hi {{name}}, please confirm your details:\n\n• Name: {{name}}\n• Insurance Type: {{insurance_type}}\n• Company: {{company}}\n{{details}}\n\nReply *Yes* to confirm or *No* to cancel.',
  forward_template:
    '📋 *New Insurance Lead*\n\n• Name: {{name}}\n• Phone: {{phone}}\n• Insurance Type: {{insurance_type}}\n• Company: {{company}}\n{{details}}\n• Submitted: {{submitted_at}}',
  success_message: 'Thank you! Your details have been confirmed and forwarded to our team. We will contact you shortly.',
  cancel_message: 'Your request has been cancelled. Send *Hi* anytime to start again.',
  already_pending_message: 'You already have a pending request. Please complete the form or reply *Yes* / *No* to your confirmation message.',
};

for (const [key, value] of Object.entries(defaults)) {
  if (Settings.get(key) === null) {
    Settings.set(key, value);
  }
}

// Ensure confirmation/forward templates include {{details}} for dynamic form fields
const conf = Settings.get('confirmation_template') || '';
if (!conf.includes('{{details}}')) {
  Settings.set('confirmation_template', defaults.confirmation_template);
}
const fwd = Settings.get('forward_template') || '';
if (!fwd.includes('{{details}}')) {
  Settings.set('forward_template', defaults.forward_template);
}
Settings.set('form_intro', defaults.form_intro);
